const e={title:"TripReel - Reiskaart Animatie App | Trip Highlight Video Maker",description:"Maak verbluffende trip highlight video's en reis recap video's met geanimeerde kaarten. Gratis reiskaart animatie app met reis route animator en 3D globe route mapping. Zet je foto's automatisch om in prachtige trip animatie video's. Privacy-first geanimeerde reiskaart app, werkt offline.",keywords:"reiskaart animatie app, trip highlight video app, reis recap video app, reis route animator app, reis recap app, geanimeerde reiskaart app, reisroute animatie app, kaart reis video app, reisverhaal maker app, trip animatie app, reisvideo maker app, vlucht animatie app, automatische reisvideo, vliegroute animatie, reis animatie app, globe animatie, foto naar video app, trip highlights, gratis reis app, offline video maker, privacy reis app, camera roll video"},i={logoAlt:"TripReel-logo",appName:"TripReel",howItWorks:"Hoe het werkt",video:"Video",features:"Functies",theApp:"De app"},a={badge:"Maak van foto's reisverhalen",title1:"Je camerarol,",title2:"volledig benut",description:"TripReel is de ultieme reiskaart animatie app die automatisch prachtige trip highlight video's en reis recap video's maakt van de locaties van je foto's. Zie je reizen tot leven komen met onze reis route animator met verbluffende geanimeerde routekaarten en vliegroutes over een 3D-wereldbol, terwijl je gegevens privé en veilig blijven.",secure:"100% veilig",worksOffline:"Werkt offline",globeAlt:"TripReel wereldbol-animatie"},t={title:"Hoe het werkt",subtitle:"Drie eenvoudige stappen om je perfecte reisvideo te maken",step1:{title:"Sta toegang tot foto's toe",description:"Geef TripReel toegang tot je fotobibliotheek. De app leest alleen locatiemetadata, niets anders."},step2:{title:"Automatische reisdetectie",description:"TripReel analyseert locatiemetadata en vindt intelligent je reizen op basis van datums en locaties."},step3:{title:"Genereer je video",description:"Kijk hoe je reis zich ontvouwt met onze reis route animator op een prachtige wereldbol-animatie, verbluffende trip highlight video's creërend die klaar zijn om te delen op sociale media."}},r={title:"Zie de magie gebeuren",subtitle:"Ontdek hoe onze reiskaart animatie app je fotobibliotheek transformeert in verbluffende trip highlight video's en reis recap video's met geanimeerde routekaarten",caption:"Zo kan je uiteindelijke trip animatie video eruitzien met onze reis route animator app"},n={title:"Alles wat je nodig hebt",subtitle:"Krachtige functies ontworpen voor moderne reizigers",twoTap:{title:"Reisvideos met twee tikken",description:"Maak verbluffende trip highlight video's en reis recap video's van je fotobibliotheek met slechts twee tikken met onze reisvideo maker app. Geen bewerking nodig."},smartTrip:{title:"Slimme reisdetectie",description:"De reis recap app vindt en groepeert automatisch je reizen door datums en locatiemetadata van je foto's te analyseren om perfecte trip highlight video's te maken."},globe:{title:"Prachtige wereldbol-animatie",description:"Zie je reis tot leven komen met onze reis route animator met een verbluffende 3D-wereldbol die je geanimeerde reisroutes en vliegroutes over de hele wereld toont in prachtige kaart reis video's."},privacy:{title:"Privacy voorop",description:"De reiskaart animatie app verwerkt alles op je apparaat. Je foto's verlaten nooit je telefoon. Maak trip animatie video's volledig offline in vliegtuigmodus."},customStyles:{title:"Aangepaste stijlen",description:"Kies uit meerdere aarde-stijlen en aanpassingen voor je trip animatie video's die passen bij jouw esthetiek en elke geanimeerde reiskaart video uniek maken."},manualControl:{title:"Handmatige bediening",description:"De reis route animator app laat je handmatig volledig nieuwe reizen toevoegen en je reisroute animatie aanpassen als locatieservices niet waren ingeschakeld op je apparaat."}},o={title:"Creatieve video-ideeën",subtitle:"Laat je inspireren door wat je kunt maken met TripReel, je reisverhaal maker app. Van snelle weekendtrips tot jaar durende avonturen, maak verbluffende trip highlight video's en reis recap video's voor elke reis.",description:"Of je nu een reiskaart-animatie maakt, een vluchtroute documenteert met onze reis route animator, of een jaarlijks reis recap app video samenstelt, TripReel maakt het moeiteloos om je herinneringen om te zetten in deelbare trip animatie video's.",ideas:{yearRecap:{title:"2025 reisoverzicht",description:"Maak automatisch je 2025 jaarlijkse reisoverzicht video met onze trip highlight video app"},europeRoadTrip:{title:"Europese roadtrip",description:"Laat je Europese avontuur zien met onze reiskaart animatie app en geanimeerde routekaarten"},southeastAsia:{title:"Zuidoost-Azië reis",description:"Visualiseer je backpackroute door meerdere landen met onze reis route animator app"},japanRail:{title:"Japan treinreis",description:"Maak kaart reis video's van je treinroutes door Japan met geanimeerde reiskaarten"},crossCountry:{title:"Dwars door de VS",description:"Verander je Amerikaanse roadtrip in een epische reisroute animatie video met onze trip animatie app"},islandHopping:{title:"Eilandhoppen",description:"Toon je reizen van eiland naar eiland met verbluffende 3D-animaties met onze reisverhaal maker app"},worldTour:{title:"Wereldreis montage",description:"Combineer meerdere reizen in één geweldige wereldreis-video met onze geanimeerde reiskaart app"},travelPlans:{title:"Reisplannen voor 2026",description:"Visualiseer en plan je spannende 2026 reisavonturen met onze reis route animator"},lifetimeTravel:{title:"Levenslang reisverhaal",description:"Maak een reis recap video met al je levenslange reizen met onze reis recap app"},regionalExplorer:{title:"Regionale verkenner",description:"Breng je avonturen in kaart door staten, provincies en regio's met onze reiskaart animatie app"},festivalCircuit:{title:"Festivalcircuit",description:"Breng je muziekfestival- en evenementenreis in kaart met geanimeerde reisroute video's"},bikeRoutes:{title:"Mijn stedentrips",description:"Laat al je stedelijke escapades zien met prachtige kaart reis video's"}}},s={title:"De app",subtitle:"Nu beschikbaar op de App Store",alt1:"Reiskaart Animatie App - Maak automatisch trip highlight video's in seconden",alt2:"Reis Route Animator - Gebruikt de locatiemetadata van je foto's voor reis recap video's",alt3:"Reisdetectie - Groepeert automatisch je reizen voor geanimeerde reiskaart video's",alt4:"Prachtige Aarde-video's - Wereldbol-animatie van je reis met onze trip animatie app",alt5:"Aangepaste Stijlen - Personaliseer je reisroute animatie video's met meerdere aarde-stijlen"},l={comingSoon:"Binnenkort",androidTitle:"Android-app komt binnenkort!",androidMessage:'De Android-versie is nog niet beschikbaar maar komt binnenkort. Stuur me een bericht op <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> en ik laat je weten wanneer het klaar is!',gotIt:"Begrepen!"},d={title:"Veelgestelde vragen",subtitle:"Alles wat je moet weten over TripReel",q1:{question:"Kan ik deze reiskaart animatie app volledig offline gebruiken in vliegtuigmodus?",answer:"Ja! Voor premium-gebruikers kan de trip highlight video app volledig offline worden gebruikt in vliegtuigmodus zonder beperkingen. Voor niet-premium gebruikers worden sommige functies ondersteund door advertenties waarvoor mogelijk tijdelijk internet nodig is, maar premium-gebruikers kunnen reis recap video's volledig offline maken zonder advertenties."},q2:{question:"Hoe verwijder ik het watermerk van mijn trip animatie video's?",answer:"Veel mensen vragen welke reisvideo maker app is gebruikt om deze geanimeerde reiskaart video's te maken. Na upgraden naar premium heb je de optie om een kleinere versie van het watermerk toe te voegen (alleen met de app-naam) of het volledig te verwijderen van je trip highlight video's als je dat wilt."},q3:{question:"Zijn mijn fotogegevens veilig en privé in deze reis route animator app?",answer:"Absoluut! De reiskaart animatie app leest alleen locatiemetadata van je foto's - we hebben nooit toegang tot, slaan op of verzenden de daadwerkelijke foto-inhoud. Alle trip animatie video verwerking gebeurt lokaal op je apparaat, en er verlaten nooit gegevens je telefoon. Je kunt dit verifiëren door reis recap video's te maken in vliegtuigmodus - het werkt perfect offline!"},q4:{question:"Wat als mijn foto's geen locatiegegevens hebben voor de reisroute animatie?",answer:"Geen probleem! Als locatieservices niet waren ingeschakeld toen je je foto's maakte, laat de reisverhaal maker app je handmatig reizen maken en zelf locaties toevoegen. De reis route animator geeft je volledige controle om je reistijdlijn aan te passen en prachtige geanimeerde reiskaart video's te maken zelfs zonder GPS-gegevens."},q5:{question:"Hoe detecteert deze reis recap video app automatisch mijn reizen?",answer:"De reiskaart animatie app analyseert de locatiemetadata en tijdstempels van je foto's om intelligent te identificeren wanneer en waar je hebt gereisd. Het groepeert nabijgelegen locaties en datums samen om automatisch je reizen te detecteren en verbluffende trip highlight video's te maken zonder handmatig werk."},q6:{question:"Kan ik het uiterlijk van mijn trip highlight video's aanpassen?",answer:"Ja! Onze trip animatie app laat je kiezen uit meerdere aarde-stijlen en verschillende aspecten van je geanimeerde reiskaart video's aanpassen om te passen bij je persoonlijke esthetiek. Premium-gebruikers krijgen toegang tot extra route-animatiestijlen, kaartthema's en vluchtroute-opties."},q7:{question:"Moet ik een account aanmaken om deze reisvideo maker app te gebruiken?",answer:"Geen account nodig! De trip animatie app werkt meteen na het downloaden. Er is geen registratie, geen login en geen persoonlijke informatie nodig. Download gewoon de reiskaart animatie app en begin meteen met het maken van je geanimeerde reisroute video's."},q8:{question:"Waarom ontbreekt een locatie in mijn geanimeerde reiskaart video?",answer:"De reis route animator app kan alleen werken met beschikbare gegevens, dus je hebt minstens een paar foto's op die locatie nodig met GPS-gegevens. Zorg ervoor dat je locatieservices had ingeschakeld toen je daar was. Soms kan slechte GPS-ontvangst verkeerde locatiegegevens veroorzaken. Als je locatie nog steeds niet verschijnt in je trip highlight video, kun je die locatie handmatig toevoegen via Reisoverzicht > Bewerken-knop. Gebruik Contact om het probleem te melden."},q9:{question:"Waar kan ik mijn reis recap video's en reisroute animaties delen?",answer:"Je kunt je trip animatie video's delen op alle sociale platforms! Onze reiskaart animatie app staat verschillende beeldverhoudingen toe (verticaal, widescreen, cinema, vierkant) voor je geanimeerde reiskaart video's om beter bij elk platform te passen - perfect voor Instagram, TikTok, YouTube, Facebook en meer."},q10:{question:"Waar kan ik een bug melden?",answer:"Neem gewoon direct contact met me op via marian@qod.ee en leg kort uit wat het probleem is."}},p={title:"E-mailondersteuning",description:"Als je feedback hebt of problemen ondervindt, neem dan gerust rechtstreeks contact met me op via deze e-mail en ik zal persoonlijk je verzoek zo snel mogelijk lezen en behandelen. Bedankt voor het gebruik van de app!",close:"Sluiten"},m={default:{title:"🍪 Cookies",message:"We gebruiken cookies op de TripReel-site om je ervaring te verbeteren. Er worden geen persoonlijke gegevens verzameld.",accept:"Accepteren",decline:"Weigeren",details:"Details"},theme:{title:"🍪 Cookies",message:"🌙 Om je themavoorkeur op te slaan, moet je essentiële cookies accepteren op de TripReel-site. Zonder deze cookies kan je themakeuze niet worden opgeslagen.",accept:"Accepteren",decline:"Weigeren",details:"Details"}},v={privacy:"App-privacybeleid",cookies:"Site-cookiebeleid",contact:"Contact",cookiePreferences:"Cookie-voorkeuren",madeWith:"Gemaakt met",forTravelers:"voor reizigers wereldwijd",copyright:"© {{year}} TripReel."},g={title:"Klaar om je reis te delen?",description:"Download TripReel vandaag en transformeer je camerarol in prachtige trip highlight video's met onze geanimeerde reiskaart app met reis route animator en reisroute animatie. Je avonturen verdienen het om gevierd te worden met verbluffende reis recap video's.",features:"Gratis te downloaden • Snel en handig • Privacy gegarandeerd"},k={title:"Over TripReel",subtitle:"Professionele trip highlight video maker en reis route animator app",howItWorks:{title:"Hoe Onze Reis Recap App Werkt",description:"De trip animatie app gebruikt intelligente algoritmes om je foto's GPS-gegevens te scannen en automatisch je reizen te detecteren. De reis route animator creëert vervolgens vloeiende, cinematische reisroute animaties die je pad door steden, landen en continenten tonen. Of je nu een snelle weekend trip highlight video maakt of een jaar durende reis recap video, de geanimeerde reiskaart app maakt het moeiteloos."},customization:{title:"Uitgebreide Aanpassing voor Je Trip Animatie Video's",description:"De reisverhaal maker app biedt aanpassingsopties op professioneel niveau om je geanimeerde reiskaart video's echt uniek te maken:",features:{videoQuality:"Kies tussen 30 FPS, 60 FPS of premium 90 FPS voor zijdezachte reisroute animaties in je trip highlight video's",bitrate:"Pas videokwaliteit (bitrate) aan van normaal naar hoog voor kristalheldere kaart reis video's zonder visuele artefacten",earthStyles:"Selecteer uit meerdere verbluffende aarde-stijlen waaronder Realistisch, Nachtverlichting, Dagkaart en Satellietweergaven voor je geanimeerde reiskaart video's",borders:"Schakel landsgrenzen in op je reis route animator met aanpasbare kleuren en dikte voor verbeterde geografievisualisatie",aspectRatios:"Maak trip animatie video's in Verticaal (9:16), Widescreen (16:9), Cinema (2.35:1) of Vierkant (1:1) formaten perfect voor Instagram, TikTok, YouTube en andere sociale platforms",tripSpeed:"Bestuur de reis route animator snelheid tussen locaties (tot 3500 km/s) om dynamische of ontspannen reis recap video's te maken",pauseDuration:"Pas pauseduur aan bij elke locatie (0.5-5 seconden) om belangrijke bestemmingen in je trip highlight video's te benadrukken",locationLabels:"Toon Stad, Regio en/of Land labels op je geanimeerde reiskaart video's om context voor je reis te bieden",pathDisplay:"Schakel tussen het tonen van alle eerdere reispaden of alleen de huidige reis in je reisroute animatie"}}},c={meta:e,header:i,hero:a,howItWorks:t,videoSection:r,features:n,videoIdeas:o,screenshots:s,appStore:l,faq:d,contact:p,cookieBanner:m,footer:v,cta:g,about:k};export{k as about,l as appStore,p as contact,m as cookieBanner,g as cta,c as default,d as faq,n as features,v as footer,i as header,a as hero,t as howItWorks,e as meta,s as screenshots,o as videoIdeas,r as videoSection};
